/**
 * Rendering a document to PDF, and caching the result.
 *
 * PDF needs a browser engine, and the only honest options are a local Chromium or
 * a remote service. A remote service means a customer's quote leaves the machine,
 * so this module drives a **locally installed** Chromium through `puppeteer-core`,
 * configured by path. When it is absent the HTML download still works and the PDF
 * is refused with a reason — never a silent fallback to something else.
 *
 * The page it renders is generated by `renderQuoteHtml`, not a URL: a renderer
 * that accepts a URL is a server-side request forgery waiting to happen. Scripts
 * are disabled and network requests are blocked, so a document cannot call home.
 *
 * The output is cached by `revisionHash + DOCUMENT_VERSION`, so a revision renders
 * once and a re-download is cheap. A cached file is never reused across revisions.
 */

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * The template's own version.
 *
 * Bump it when the layout changes: a cached PDF is keyed by this plus the
 * revision hash, so a new template renders fresh without invalidating the old
 * file for a revision nobody re-opens.
 */
export const DOCUMENT_VERSION = '1';

/** Where a rendered PDF lives, outside any public directory. */
export function cacheKey(revisionHash: string): string {
  return createHash('sha256')
    .update(`${revisionHash}:${DOCUMENT_VERSION}`)
    .digest('hex');
}

/** The path for one revision's PDF. */
export function cachePath(root: string, revisionHash: string): string {
  return join(root, `${cacheKey(revisionHash)}.pdf`);
}

/** Read a cached PDF, or `null` when it has not been rendered. */
export function readCachedPdf(root: string, revisionHash: string): Buffer | null {
  const path = cachePath(root, revisionHash);
  return existsSync(path) ? readFileSync(path) : null;
}

/** Write a rendered PDF into the cache. */
export function writeCachedPdf(root: string, revisionHash: string, pdf: Buffer): void {
  mkdirSync(root, { recursive: true });
  writeFileSync(cachePath(root, revisionHash), pdf);
}

/** Why a PDF could not be produced, when it could not. */
export class PdfUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PdfUnavailableError';
  }
}

export interface RenderOptions {
  /** The Chromium executable, from configuration. */
  executablePath: string | undefined;
  timeoutMs?: number;
}

/**
 * Render HTML to PDF with a local Chromium.
 *
 * The browser is launched per render rather than pooled: a quote PDF is a rare,
 * short operation, and a pool is a long-lived process holding a customer's
 * document in memory. Isolation is worth the launch cost here.
 */
export async function renderPdf(html: string, options: RenderOptions): Promise<Buffer> {
  const executablePath = options.executablePath;
  if (executablePath === undefined || executablePath === '' || !existsSync(executablePath)) {
    throw new PdfUnavailableError(
      'PDF rendering is not configured on this server. Download the HTML instead, or ask the operator to install Chromium and set CHROME_PATH.',
    );
  }

  const timeoutMs = options.timeoutMs ?? 20_000;

  // `puppeteer-core` is imported lazily so the app starts without it installed;
  // only a PDF request needs it.
  const puppeteer = (await import('puppeteer-core')) as typeof import('puppeteer-core');
  // A launch timeout as well as a render timeout. A Chromium that starts but
  // never finishes handshaking would otherwise hang the request; because the send
  // runs inline in an HTTP request, the reverse proxy would give up first and
  // report a 502 instead of "the PDF renderer timed out".
  const browser = await puppeteer.launch({
    executablePath,
    headless: true,
    args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    timeout: timeoutMs,
  });

  try {
    const page = await browser.newPage();
    // A quote is text and vector shapes. No script, no network, no file access.
    await page.setJavaScriptEnabled(false);
    await page.setRequestInterception(true);
    page.on('request', (request) => {
      const url = request.url();
      if (url.startsWith('data:') || url.startsWith('about:')) {
        void request.continue();
      } else {
        void request.abort();
      }
    });

    await page.setContent(html, { waitUntil: 'load', timeout: timeoutMs });
    const pdf = await page.pdf({
      format: 'A4',
      printBackground: true,
      margin: { top: '18mm', right: '16mm', bottom: '18mm', left: '16mm' },
      timeout: timeoutMs,
    });

    return Buffer.from(pdf);
  } finally {
    await browser.close();
  }
}

/** The configured Chromium path, or `undefined`. */
export function chromePathFromEnv(): string | undefined {
  const value = process.env.CHROME_PATH;
  return value === undefined || value.trim() === '' ? undefined : value;
}
